from functools import lru_cache

def count_valid_parens(n: int) -> int:
    @lru_cache(maxsize=None)
    def catalan(num: int) -> int:
        if num <= 1:
            return 1
        total = 0
        for i in range(num):
            total += catalan(i) * catalan(num - 1 - i)
        return total
    return catalan(n)

def edit_distance(s1: str, s2: str) -> int:
    m, n = len(s1), len(s2)
    # Use two rows to save space
    prev = list(range(n + 1))
    curr = [0] * (n + 1)
    for i in range(1, m + 1):
        curr[0] = i
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j], curr[j - 1], prev[j - 1])
        prev, curr = curr, prev
    return prev[n]
